// PROTOTYPE: diagnostic only. JK02_24S / JK02_32S are frame layouts, not cell counts.
const raw=msg.payload||{};
if(raw.type!==2 || raw.crc_ok!==true || typeof raw.raw_hex!=="string" || raw.raw_hex.length!==600) return null;
const b=Buffer.from(raw.raw_hex,"hex");
if(b.length!==300 || b.subarray(0,4).toString("hex")!=="55aaeb90" || b[4]!==2) return null;
if(b.subarray(0,299).reduce((s,v)=>(s+v)&255,0)!==b[299]) return null;
const profiles=[
  {name:"JK02_24S",n:24,mask:54,voltage:118,current:126,soc:141,t1:130,t2:132,mos:134,cap:146,cycles:150,charge:166,discharge:167,error:136,errorSize:2},
  {name:"JK02_32S",n:32,mask:70,voltage:150,current:158,soc:173,t1:162,t2:164,mos:144,cap:178,cycles:182,charge:198,discharge:199,error:166,errorSize:4}
];
function parse(p){
 const mask=b.readUInt32LE(p.mask),cells=[];
 for(let i=0;i<p.n;i++) if((mask>>>i)&1) cells.push({number:i+1,voltage_v:b.readUInt16LE(6+2*i)/1000});
 const voltage=b.readUInt32LE(p.voltage)/1000,current=b.readInt32LE(p.current)/1000,soc=b[p.soc];
 const sum=cells.reduce((x,c)=>x+c.voltage_v,0);
 const rawTemperatures=[p.t1,p.t2,p.mos].map(x=>b.readInt16LE(x));
 const labels=["T1","T2","MOS"];
 const temperatures=rawTemperatures.map(x=>x/10);
 const invalid_temperature_channels=labels.filter((label,i)=>
    temperatures[i]< -80||temperatures[i]>160);
 // Electrical and cell checks remain strictly enforced. An invalid/absent
 // temperature probe must NOT invalidate otherwise consistent pack data.
 // Require at least TWO plausible temperature readings to keep warnings useful.
 if(cells.length<4 || cells.some(c=>c.voltage_v<1.5||c.voltage_v>4.5) ||
    voltage<5 || voltage>170 || Math.abs(sum-voltage)>Math.max(1.5,voltage*0.04) ||
    soc>100 || Math.abs(current)>3000 ||
    invalid_temperature_channels.length>1) return null;
 const values=cells.map(c=>c.voltage_v);
 return {address:raw.address,sequence:raw.sequence,format:p.name,validation:"provisional_compare_with_BatMON",
   source_crc_ok:true,cell_count:cells.length,cells,
   voltage_v:+voltage.toFixed(3),current_a:+current.toFixed(3),power_w:+(voltage*current).toFixed(1),
   soc_pct:soc,cell_min_v:Math.min(...values),cell_max_v:Math.max(...values),
   cell_delta_mv:Math.round((Math.max(...values)-Math.min(...values))*1000),cell_sum_v:+sum.toFixed(3),
   temp1_c:invalid_temperature_channels.includes("T1")?null:temperatures[0],
   temp2_c:invalid_temperature_channels.includes("T2")?null:temperatures[1],
   mos_temp_c:invalid_temperature_channels.includes("MOS")?null:temperatures[2],
   temperature_quality:invalid_temperature_channels.length?"partial_unverified":"ok",
   invalid_temperature_channels,
   invalid_temperature_raw_tenths:labels.reduce((acc,label,i)=>{
     if(invalid_temperature_channels.includes(label)) acc[label]=rawTemperatures[i];
     return acc;
   },{}),
   temperature_sensor_absent_mask:p.name==="JK02_32S"?b[214]:null,
   nominal_capacity_ah:b.readUInt32LE(p.cap)/1000,cycles:b.readUInt32LE(p.cycles),
   charging_mos:b[p.charge]===1,discharging_mos:b[p.discharge]===1,
   error_mask:p.errorSize===4?b.readUInt32LE(p.error):b.readUInt16LE(p.error)};
}
const found=profiles.map(parse).filter(Boolean);
if(found.length!==1){
 const key="reject:"+raw.address,now=Date.now(),last=context.get(key)||0;
 if(now-last<15000) return null;
 context.set(key,now);
 node.status({fill:"yellow",shape:"ring",text:found.length?"Ambiguous layout":"Unknown JK layout"});
 return [null,{topic:"jk/"+raw.address+"/decoder_validation",payload:{
  address:raw.address,sequence:raw.sequence,
  reason:found.length?"ambiguous_protocol":"no_plausible_profile",
  matching_formats:found.map(x=>x.format),raw_hex:raw.raw_hex}}];
}
const out=found[0];
context.set("latest:"+raw.address,out);
node.status({fill:out.temperature_quality==="ok"?"green":"yellow",shape:"dot",
 text:out.format+" "+out.voltage_v+"V "+out.soc_pct+"%"+
 (out.invalid_temperature_channels.length?" TEMP "+out.invalid_temperature_channels.join(",")+" invalide":"")});
return [{topic:"jk/"+raw.address+"/decoded_diagnostic",payload:out},null];
